pages=[]
def page(id,title,kicker,blocks): pages.append(dict(id=id,title=title,kicker=kicker,blocks=blocks))
def p(t):return {'type':'p','text':t}
def bullets(*items):return {'type':'bullets','items':items}
def table(head,rows):return {'type':'table','head':head,'rows':rows}
def image(code,caption):return {'type':'image','code':code,'caption':caption}
def diagram(kind):return {'type':'diagram','kind':kind}

